<body>
  <div class="wrap">
    <header>
      <h1>Memory Match</h1>
      <p class="hint">Flip two cards to find a matching pair. Clear all 8 pairs in as few moves as you can.</p>
    </header>

    <div class="toolbar">
      <div class="stats">
        <div class="stat"><span class="stat-label">Moves</span><span class="stat-value" id="moves">0</span></div>
        <div class="stat"><span class="stat-label">Pairs</span><span class="stat-value" id="pairs">0 / 8</span></div>
      </div>
      <button class="btn" id="newGame" type="button">New game</button>
    </div>

    <div class="board" id="board" aria-label="Memory card grid"></div>

    <div class="win" id="win" hidden>
      <h2>You won!</h2>
      <p id="winText"></p>
      <button class="btn" id="playAgain" type="button">Play again</button>
    </div>

    <p class="sr-only" id="status" role="status" aria-live="polite"></p>
  </div>

<script>
(function () {
  const SYMBOLS = ['★','♥','♣','♦','☀','☾','♪','✿'];
  const board = document.getElementById('board');
  const movesEl = document.getElementById('moves');
  const pairsEl = document.getElementById('pairs');
  const winEl = document.getElementById('win');
  const winText = document.getElementById('winText');
  const status = document.getElementById('status');

  let cards = [], first = null, second = null, lock = false;
  let moves = 0, matched = 0, best = null;

  function shuffle(a) {
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }

  function announce(msg) { status.textContent = msg; }

  function updateStats() {
    movesEl.textContent = moves;
    pairsEl.textContent = matched + ' / 8';
  }

  function newGame() {
    first = null; second = null; lock = false; moves = 0; matched = 0;
    winEl.hidden = true;
    const deck = shuffle(SYMBOLS.concat(SYMBOLS));
    cards = [];
    board.innerHTML = '';
    deck.forEach(function (sym, i) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'card';
      btn.dataset.index = i;
      btn.setAttribute('aria-label', 'Card ' + (i + 1) + ', face down');
      btn.innerHTML =
        '<span class="card-inner">' +
          '<span class="face face-back" aria-hidden="true"></span>' +
          '<span class="face face-front" aria-hidden="true">' + sym + '</span>' +
        '</span>';
      btn.addEventListener('click', function () { onCard(btn); });
      board.appendChild(btn);
      cards.push({ el: btn, symbol: sym, matched: false });
    });
    updateStats();
    announce('New game started. 8 pairs shuffled and ready.');
    save();
  }

  function onCard(btn) {
    if (lock) return;
    const i = +btn.dataset.index, card = cards[i];
    if (card.matched || btn.classList.contains('flipped')) return;

    btn.classList.add('flipped');
    btn.setAttribute('aria-label', 'Card ' + (i + 1) + ', showing ' + card.symbol);

    if (first === null) { first = card; return; }
    second = card;
    moves++;
    updateStats();
    lock = true;

    if (first.symbol === second.symbol) {
      first.matched = true; second.matched = true;
      first.el.classList.add('matched');
      second.el.classList.add('matched');
      first.el.setAttribute('aria-label', 'Card matched');
      second.el.setAttribute('aria-label', 'Card matched');
      matched++;
      announce('Match! ' + matched + ' of 8 pairs found.');
      updateStats();
      first = null; second = null; lock = false;
      if (matched === 8) finish();
    } else {
      announce('No match. Cards will flip back.');
      setTimeout(function () {
        first.el.classList.remove('flipped');
        second.el.classList.remove('flipped');
        first.el.setAttribute('aria-label', 'Card ' + cards.indexOf(first) + 1 + ', face down');
        second.el.setAttribute('aria-label', 'Card ' + cards.indexOf(second) + 1 + ', face down');
        first = null; second = null; lock = false;
      }, 850);
    }
    save();
  }

  function finish() {
    if (best === null || moves < best) { best = moves; save(); }
    const record = (moves === best) ? ' That is your best score so far.' : '';
    winText.innerHTML = 'You cleared all 8 pairs in <b>' + moves + '</b> moves.' + record;
    winEl.hidden = false;
    announce('You won in ' + moves + ' moves!');
  }

  function save() {
    if (window.alfy && window.alfy.storage) {
      try {
        window.alfy.storage.set('memory-match', {
          cards: cards.map(function (c) { return { symbol: c.symbol, matched: c.matched }; }),
          moves: moves, matched: matched, best: best
        });
      } catch (e) {}
    }
  }

  function restore() {
    if (!(window.alfy && window.alfy.storage)) return;
    window.alfy.storage.get('memory-match').then(function (data) {
      if (!data || !Array.isArray(data.cards) || data.cards.length !== 16) { newGame(); return; }
      best = (typeof data.best === 'number') ? data.best : null;
      moves = data.moves || 0;
      matched = data.matched || 0;
      cards = [];
      board.innerHTML = '';
      data.cards.forEach(function (c, i) {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'card';
        btn.dataset.index = i;
        btn.setAttribute('aria-label', 'Card ' + (i + 1) + ', face down');
        btn.innerHTML =
          '<span class="card-inner">' +
            '<span class="face face-back" aria-hidden="true"></span>' +
            '<span class="face face-front" aria-hidden="true">' + c.symbol + '</span>' +
          '</span>';
        btn.addEventListener('click', function () { onCard(btn); });
        board.appendChild(btn);
        cards.push({ el: btn, symbol: c.symbol, matched: !!c.matched });
      });
      cards.forEach(function (c) {
        if (c.matched) {
          c.el.classList.add('matched');
          c.el.setAttribute('aria-label', 'Card matched');
        }
      });
      updateStats();
      if (matched === 8) finish();
      announce('Game restored from a previous session.');
    }).catch(function () { newGame(); });
  }

  document.getElementById('newGame').addEventListener('click', newGame);
  document.getElementById('playAgain').addEventListener('click', newGame);

  restore();
})();
</script>
</body>
</html>
